// gshare branch predictor, 128-entry PHT, 2-bit saturating counters,
// one prediction/training interface per cycle.
module TopModule(
    input clk,
    input areset,
    input predict_valid,
    input [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    input train_valid,
    input train_taken,
    input train_mispredicted,
    input [6:0] train_history,
    input [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] global_history;
    reg [6:0] next_global_history;
    wire [6:0] index = global_history ^ predict_pc;
    wire [6:0] next_index = next_global_history ^ train_pc;
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) pht[i] <= 2'b11;
            global_history <= 7'd0;
            next_global_history <= 7'd0;
            predict_taken <= 1'b0;
            predict_history <= 7'd0;
        end else begin
            if (predict_valid) begin
                predict_taken <= pht[index][1] & pht[index][0];
                predict_history <= global_history;
            end
            if (train_valid) begin
                pht[next_index] <= (train_taken ? {pht[next_index][0], 1'b1} : {1'b0, pht[next_index][1]}) + (train_mispredicted ? 2'b11 : pht[next_index]);
                next_global_history <= train_history;
            end
            global_history <= next_global_history;
        end
    end
endmodule

