samples.raw_completion:
// GSHARE branch predictor, with 128-entry saturating 2-bit counter per
// history register index, hashed (using XOR) into the index. The global
// branch history register is also used for predicting and training.
module TopModule(
    input  clk,
    input  areset,
    // prediction interface: for fetching instructions
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken;
    output reg [6:0] predict_history;
    // training interface: for adapting predictions to actual outcomes
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] counters [0:127];
    reg [6:0] history;
    wire [6:0] index = history ^ predict_pc;
    wire [1:0] counter = counters[index];
    always @(*) begin
        predict_taken = counter[1] & counter[0];
        predict_history = history;
    end
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) counters[i] <= 2'b00;
            history <= 7'd0;
        end else begin
            if (predict_valid) begin
                counter[1] <= counter[1] + (predict_taken ? 2'b01 : 2'b10);
                counter[0] <= counter[0] + (predict_taken ? 2'b10 : 2'b01);
                history <= (history << 1) | predict_taken;
            end
            if (train_valid) begin
                counter[1] <= counter[1] + (train_taken ? 2'b01 : 2'b10);
                counter[0] <= counter[0] + (train_taken ? 2'b10 : 2'b01);
                if (train_mispredicted) history <= train_history;
                else history <= (history << 1) | train_taken;
            end
        end
    end
endmodule

