// GSHARE ONE-LEVEL BRANCH PREDICTOR
// (7-bit pc, 7-bit global history, hashed into a 7-bit index -> direct
// lookup in a 128-entry saturating 2-bit counter table)
module TopModule (
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] counter [0:127];
    reg [6:0] global_history;

    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) counter[i] <= 2'b11;
            global_history <= 7'd0;
        end else begin
            if (train_valid) begin
                counter[{global_history, train_pc}][train_taken] <= counter[{global_history, train_pc}][train_taken] + 2'b01;
                counter[{global_history, train_pc}][~train_taken] <= counter[{global_history, train_pc}][~train_taken] - 2'b01;
                if (train_mispredicted) global_history <= {global_history[5:0], train_taken};
            end
            if (predict_valid) begin
                predict_taken <= counter[{global_history, predict_pc}][0] > counter[{global_history, predict_pc}][1];
                predict_history <= global_history;
                global_history <= {global_history[5:0], predict_taken};
            end
        end
    end
endmodule

