// GShare branch predictor, as described in the reference paper, with an extra
// stage of pipeline that removes the need for an extra register stage to
// pipeline the prediction register update.
module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] ghr;
    wire [6:0] ind = ghr ^ predict_pc;
    wire [1:0] pht_pred = pht[ind];
    reg predict_taken_reg;
    reg [6:0] predict_history_reg;
    always @(*) begin
        predict_taken_reg = pht_pred == 2'b01 || pht_pred == 2'b11;
    end
    always @(*) begin
        predict_history_reg = (predict_taken_reg ? ghr + 1 : ghr - 1) & 7'h7F;
    end
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1)
                pht[i] <= 2'b11;
            ghr <= 7'h00;
        end else begin
            if (predict_valid) begin
                predict_taken <= predict_taken_reg;
                predict_history <= predict_history_reg;
                ghr <= (predict_taken ? ghr + 1 : ghr - 1) & 7'h7F;
            end
            if (train_valid) begin
                pht[ind] <= (train_taken ? (pht[ind] < 2'b11 ? pht[ind] + 1 : 2'b11) : (pht[ind] > 2'b00 ? pht[ind] - 1 : 2'b00));
                if (train_mispredicted)
                    ghr <= train_history;
                else
                    ghr <= (predict_taken_reg ? ghr + 1 : ghr - 1) & 7'h7F;
            end
        end
    end
endmodule

