    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] ctr [0:127];
    reg [6:0] global_history;
    reg [6:0] history_reg;
    wire [6:0] history_combined = {global_history, history_reg};
    wire [6:0] index = predict_pc ^ global_history;
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) ctr[i] <= 2'b10;
