// Gshare branch predictor with 7-bit PC, 7-bit global history, hashed
// into a 7-bit index, and 128-entry saturating 2-bit counter table. The
// branch history register is updated at the end of every fetch stage (i.e.
// after the pipeline has had a chance to process the instruction). This
// means that the branch history is implicitly updated with every branch
// prediction and doesn't need to be updated explicitly on mispredictions
// or taken branches.
module TopModule(
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] counter_table [0:127];
    reg [6:0] global_history;
    reg [1:0] pred_counter;
    wire [6:0] index = global_history ^ predict_pc;
    wire predict_branch = predict_valid & (counter_table[index] > 1);
    wire predict_ntaken = predict_valid & (counter_table[index] == 1);
    wire predict_taken = predict_valid & (counter_table[index] == 2);
    wire [1:0] new_counter = train_taken ? counter_table[index] + 1 : counter_table[index] - 1;
    wire [1:0] new_counter_mispred = train_taken ? 2 : 1;
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) counter_table[i] <= 2'b11;
            global_history <= 7'd0;
        end else begin
            if (train_valid) begin
                counter_table[global_history ^ train_pc] <= new_counter_mispred;
                global_history <= (global_history << 1) | train_taken;
            end
            if (predict_valid) begin
                counter_table[index] <= new_counter;
                global_history <= (global_history << 1) | predict_taken;
            end
        end
    end
    always @(*) predict_history = global_history;
endmodule

