// Gshare branch predictor, 7-bit pc, 7-bit global history, hashed (using
// xor) into a 7-bit index. This index accesses a 128-entry table of
// two-bit saturating counters.
module TopModule (
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] global_history;
    wire [6:0] hash = global_history ^ predict_pc;
    reg [1:0] counter;
    reg [1:0] next_counter;
    reg predict_prediction;
    always @(*) begin
        counter = pht[hash];
        predict_prediction = counter[1] && counter[0];
        predict_taken = predict_prediction && predict_valid;
    end
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1)
                pht[i] <= 2'b00;
            global_history <= 7'b0;
        end else begin
            if (predict_valid)
                predict_history <= global_history;
            if (train_valid) begin
                pht[hash] <= train_taken ? {counter[1], 1'b1} : {counter[1], 1'b0};
                global_history <= (global_history << 1) | train_taken;
            end else if (predict_valid) begin
                pht[hash] <= predict_taken ? {counter[1], 1'b1} : {counter[1], 1'b0};
                global_history <= (global_history << 1) | predict_taken;
            end
        end
    end
endmodule

