// gshare branch predictor with 128-entry saturating 2-bit counter PHT
// (hashed into a 7-bit index), explicit prediction interface (for use in
// the fetch stage) and training interface (for use in the Execute stage,
// after the branch has been executed).
module TopModule(
    input  clk,
    input  areset,
    // Prediction interface (for use in the fetch stage)
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    // Training interface (for use in the execute stage, after the branch
    // has been executed).
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] history;
    wire [6:0] hash = predict_pc ^ history;
    wire [1:0] counter = pht[hash];
    reg predict_reg;
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) pht[i] <= 2'b11;
            history <= 7'd0;
            predict_reg <= 1'b0;
        end else begin
            if (predict_valid) begin
                predict_taken <= counter[1] && counter[0];
                predict_history <= history;
                predict_reg <= counter[1] && counter[0];
            end
            if (train_valid) begin
                pht[hash] <= counter[1] && counter[0] && !train_taken ||
                             !counter[1] && !counter[0] && train_taken ? 2'b00 :
                             !counter[1] &&  counter[0] && !train_taken ||
                             !counter[1] &&  counter[0] &&  train_taken ? 2'b01 :
                              counter[1] && !counter[0] && !train_taken ||
                              counter[1] && !counter[0] &&  train_taken ? 2'b10 : 2'b11;
                if (train_mispredicted) history <= train_history;
                else history <= (history + 7'd1) & 7'h7F;
            end
        end
    end
    // Pipeline the prediction register stage one cycle to go from
    // combinational (per-branch) to per-cycle predicted branch direction.
    reg predict_reg2;
    always @(posedge clk) predict_reg2 <= predict_reg;
    assign predict_taken = predict_reg2;
endmodule

