// gshare branch predictor, hashed into a 7-bit index accessed by a
// 128-entry saturating 2-bit counter table.
module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [6:0] history_reg;
    reg [6:0] history_next;
    reg [1:0] counter_table [0:127];
    always @(*) begin
        counter_table[predict_pc[6:0]] = 2'b00;
        counter_table[train_pc[6:0]] = 2'b00;
    end
    always @(posedge clk) begin
        if (areset) begin
            history_reg <= 7'd0;
        end else begin
            history_reg <= history_next;
        end
    end
    always @(*) begin
        if (predict_valid) begin
            predict_taken = counter_table[predict_pc[6:0]][1] & (predict_pc[6:0] == history_reg);
            predict_history = history_reg;
        end
        if (train_valid) begin
            counter_table[train_pc[6:0]] = counter_table[train_pc[6:0]] + (train_taken ? 2'b01 : 2'b10) - (train_mispredicted ? 2'b10 : 2'b00);
            history_next = (train_mispredicted ? train_history : history_reg) ^ predict_pc[6:0];
        end
    end
endmodule

