// gshare 2-bit saturating counter branch predictor
module TopModule(
    input clk,
    input areset,
    // prediction interface
    input predict_valid,
    input [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    // training interface
    input train_valid,
    input train_taken,
    input train_mispredicted,
    input [6:0] train_history,
    input [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] history;
    reg [6:0] lru_addr;
    integer i;
    reg [1:0] pht_pred;
    wire [6:0] pc_index;
    wire predict_taken_reg;
    wire [6:0] predict_history_reg;
    always @(*) begin
        pc_index = history ^ predict_pc;
        pht_pred = pht[pc_index];
        predict_taken_reg = pht_pred[1] | (pht_pred[0] & ~predict_taken);
    end
    always @(posedge clk) begin
        if (areset) begin
            for (i = 0; i < 128; i = i + 1) pht[i] <= 2'b11;
            history <= 7'b0;
            lru_addr <= 7'b0;
        end else begin
            if (predict_valid) begin
                predict_taken <= predict_taken_reg;
                predict_history <= predict_history_reg;
                if (predict_taken) history <= history + 1;
                else history <= history - 1;
            end
            if (train_valid) begin
                pht[pc_index] <= (train_taken && predict_taken_reg) ? 2'b11 :
                                 (train_taken && ~predict_taken_reg) ? 2'b10 :
                                 (~train_taken && predict_taken_reg) ? 2'b01 : 2'b00;
                history <= train_history;
                if (train_mispredicted) lru_addr <= train_pc;
            end
        end
    end
    always @(posedge clk) begin
        if (areset) begin
            predict_history_reg <= 7'b0;
        end else begin
            if (predict_valid && predict_taken) predict_history_reg <= history;
            else if (predict_valid && ~predict_taken) predict_history_reg <= history - 1;
            else predict_history_reg <= lru_addr;
        end
    end
endmodule

